def transform(g):
    h,w=len(g),len(g[0])
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    out=[row[:] for row in g]
    from collections import defaultdict
    rows=defaultdict(list); cols=defaultdict(list)
    for r,c in pts: rows[r].append(c); cols[c].append(r)
    segs=[]  # (kind, fixed, lo, hi)
    for r,cs in rows.items():
        for i in range(len(cs)):
            for j in range(i+1,len(cs)):
                segs.append(('h',r,min(cs[i],cs[j]),max(cs[i],cs[j])))
    for c,rs in cols.items():
        for i in range(len(rs)):
            for j in range(i+1,len(rs)):
                segs.append(('v',c,min(rs[i],rs[j]),max(rs[i],rs[j])))
    def draw_h(r,a,b):
        for c in range(a+1,b):
            if out[r][c]==0: out[r][c]=3
    def draw_v(c,a,b):
        for r in range(a+1,b):
            if out[r][c]==0: out[r][c]=3
    for k,f,a,b in segs:
        (draw_h if k=='h' else draw_v)(f,a,b)
    used=set()
    for k,f,a,b in segs:
        for r in range(a+1,b): used.add((r,f))
        for c in range(a,b+1): used.add((f,c))
    for p in pts:
        if p in used: continue
        r,c=p
        best=None
        for k,f,a,b in segs:
            if k=='h' and a<=c<=b:
                d=abs(r-f)
                if best is None or d<best[0]: best=(d,'h',f)
            if k=='v' and a<=r<=b:
                d=abs(c-f)
                if best is None or d<best[0]: best=(d,'v',f)
        if best:
            d,k,f=best
            if k=='h': draw_v(c,min(r,f),max(r,f))
            else: draw_h(r,min(c,f),max(c,f))
    return out

